#include "account_edit_page.hpp"
#include "account_edit_model.hpp"
#include <QComboBox>
#include <QLineEdit>
#include <QTextEdit>
#include <QCheckBox>
#include <QLabel>
#include <QPushButton>
#include <QScrollArea>
#include <QVBoxLayout>
#include <QFormLayout>
#include <QSignalBlocker>
#include <stdexcept>
AccountEditPage::AccountEditPage(AccountEditHost h,QWidget*p):QWidget(p),host(h){setObjectName("accountEditPage");auto layout=new QVBoxLayout(this);auto scroll=new QScrollArea;scroll->setWidgetResizable(true);auto body=new QWidget;scroll->setWidget(body);layout->addWidget(scroll,1);auto form=new QFormLayout(body);choice=new QComboBox;choice->setObjectName("accountEditChoice");form->addRow("已有账户",choice);name=new QLineEdit;broker=new QLineEdit;masked=new QLineEdit;cash=new QLineEdit;note=new QTextEdit;name->setObjectName("accountEditName");broker->setObjectName("accountEditBroker");masked->setObjectName("accountEditMasked");cash->setObjectName("accountEditCash");note->setObjectName("accountEditNote");cash->setPlaceholderText("未记录时为空，不代表0元");form->addRow("账户名称",name);form->addRow("券商 / 来源",broker);form->addRow("脱敏账户标识",masked);form->addRow("账户备注",note);editCash=new QCheckBox("修改手工现金余额");editCash->setObjectName("accountEditCashEnabled");form->addRow(editCash);form->addRow("现金（元）",cash);message=new QLabel("保持账户ID；现金为手工余额，不生成出入金或交易流水");message->setObjectName("accountEditMessage");message->setWordWrap(true);layout->addWidget(message);auto buttons=new QHBoxLayout;layout->addLayout(buttons);auto read=new QPushButton("重读");auto previewButton=new QPushButton("预览变更");save=new QPushButton("保存");auto cancelButton=new QPushButton("取消");save->setObjectName("accountEditSave");cancelButton->setObjectName("accountEditCancel");for(auto b:{read,previewButton,save,cancelButton}){b->setMinimumHeight(32);buttons->addWidget(b);}connect(choice,&QComboBox::currentIndexChanged,this,[this]{if(!loading){if(back()){QSignalBlocker block(choice);choice->setCurrentIndex(choice->findData(expected["id"].toString()));}else select();}});for(auto field:{name,broker,masked,cash})connect(field,&QLineEdit::textChanged,this,[this]{changed();});connect(note,&QTextEdit::textChanged,this,[this]{changed();});connect(editCash,&QCheckBox::toggled,this,[this](bool value){cash->setEnabled(value);changed();});connect(read,&QPushButton::clicked,this,[this]{reload();});connect(previewButton,&QPushButton::clicked,this,[this]{preview();});connect(save,&QPushButton::clicked,this,[this]{commit();});connect(cancelButton,&QPushButton::clicked,this,[this]{cancel();});reload();}
void AccountEditPage::reload(){if(!active)return;try{accounts=host.loadAccounts?host.loadAccounts():QJsonArray{};loading=true;choice->clear();for(auto v:accounts){auto a=v.toObject();accountEdit::draft(a);choice->addItem(a["name"].toString()+" · "+a["id"].toString(),a["id"].toString());}loading=false;select();}catch(const std::exception&e){loading=false;proposal={};save->setEnabled(false);message->setText(QString::fromUtf8(e.what()));}}
void AccountEditPage::select(){expected={};for(auto v:accounts)if(v.toObject()["id"]==choice->currentData().toString())expected=v.toObject();cancel();}
QJsonObject AccountEditPage::currentDraft()const{return {{"name",name->text()},{"broker",broker->text()},{"maskedNumber",masked->text()},{"note",note->toPlainText()},{"cashText",cash->text()},{"editCash",editCash->isChecked()}};}
void AccountEditPage::changed(){if(loading)return;proposal={};save->setEnabled(false);}
void AccountEditPage::cancel(){loading=true;proposal={};if(!expected.isEmpty()){auto d=accountEdit::draft(expected);name->setText(d["name"].toString());broker->setText(d["broker"].toString());masked->setText(d["maskedNumber"].toString());note->setPlainText(d["note"].toString());cash->setText(d["cashText"].toString());}editCash->setChecked(false);cash->setEnabled(false);save->setEnabled(false);loading=false;message->setText("草稿已恢复；未写入。现金为手工余额，不是交易流水。");}
void AccountEditPage::preview(){if(!active||expected.isEmpty())return;try{proposal=accountEdit::propose(expected,currentDraft());QString text=proposal["changed"].toBool()?"变更已预览，保存前核对。":"没有变更，不写入。";for(auto key:{"name","broker","maskedNumber","note"})if(expected.value(key)!=proposal["candidate"].toObject().value(key))text+="\n"+QString(key==QString("name")?"账户名称":key==QString("broker")?"券商 / 来源":key==QString("maskedNumber")?"脱敏标识":"账户备注")+"已变更，请在表单核对。";if(proposal["cashEdited"].toBool())text+="现金将记录为 "+QString::number(proposal["candidate"].toObject()["cashBalance"].toDouble(),'f',2)+" 元。";text=(proposal["warning"].toString().isEmpty()?QString():proposal["warning"].toString()+"\n")+text+"\n仅已有账户元信息/手工现金；其他历史与流水保留。";if(!host.atomicCas)text+="\n保存功能尚未接通，当前草稿未写入。";message->setText(text);save->setEnabled(proposal["changed"].toBool()&&host.atomicCas&&bool(host.compareAndSave));}catch(const std::exception&e){proposal={};save->setEnabled(false);message->setText(QString::fromUtf8(e.what()));}}
void AccountEditPage::commit(){if(!active||proposal.isEmpty()||!proposal["changed"].toBool()||!host.atomicCas||!host.compareAndSave)return;try{auto now=accountEdit::propose(expected,currentDraft());if(now!=proposal)throw std::runtime_error("预览已变化，请重新预览");auto committed=host.compareAndSave(expected,proposal["candidate"].toObject());if(committed["id"]!=expected["id"]||committed["type"]!=expected["type"])throw std::runtime_error("宿主返回了不同账户，未采纳");expected=committed;for(int n=0;n<accounts.size();++n)if(accounts[n].toObject()["id"]==expected["id"])accounts[n]=committed;cancel();message->setText("账户修改已保存；ID/原有历史保留，未生成交易。");}catch(const std::exception&e){save->setEnabled(false);message->setText(QString::fromUtf8(e.what()));}}
void AccountEditPage::setActive(bool value){active=value;if(!value){proposal={};save->setEnabled(false);}}

QJsonObject AccountEditPage::saveState()const{return {{"schema","account-editor-view/v1"},{"expected",expected},{"draft",currentDraft()}};}
void AccountEditPage::restoreState(QJsonObject s){
 if(s["schema"]!="account-editor-view/v1"||!s["expected"].isObject()||!s["draft"].isObject())throw std::runtime_error("账户草稿状态无效，未采用");
 auto old=s["expected"].toObject(),d=s["draft"].toObject();accountEdit::propose(old,d);loading=true;
 int index=choice->findData(old["id"].toString());if(index<0){accounts.append(old);choice->addItem(old["name"].toString()+" · 原草稿（当前账户未找到）",old["id"].toString());index=choice->count()-1;}
 choice->setCurrentIndex(index);expected=old;name->setText(d["name"].toString());broker->setText(d["broker"].toString());masked->setText(d["maskedNumber"].toString());note->setPlainText(d["note"].toString());cash->setText(d["cashText"].toString());editCash->setChecked(d["editCash"].toBool());cash->setEnabled(editCash->isChecked());proposal={};save->setEnabled(false);loading=false;message->setText("未保存账户草稿已恢复；请重新预览，版本冲突将拒绝保存。");
}
bool AccountEditPage::back(){try{if(!expected.isEmpty()&&accountEdit::propose(expected,currentDraft())["changed"].toBool()){message->setText("账户草稿未保存，请明确取消或预览保存后返回。");return true;}}catch(...){message->setText("账户草稿尚未处理，请先取消或修正。");return true;}return false;}
